// ─────────────────────────────────────────────────────────
//  Pictures for the bhajan groups.
//
//  Two sources, and the credit always says which:
//
//    Wikimedia Commons — generated by
//      scripts/wordpress/fetch-devata-images.mjs, which asks the API
//      for each file's real licence and author and refuses anything
//      non-free. The credits below are whatever Commons actually said,
//      not what anyone typed. Several are Raja Ravi Varma paintings,
//      long out of copyright: a card needs a picture that reads at
//      210px, and a dark temple carving does not. The first pass used
//      carvings and one of them turned out to be a photograph of a
//      signboard outside the temple.
//
//    The site's owner — four photographs of temple murtis he supplied.
//      Their original photographer and licence are not recorded, so
//      they carry no source link and the credit names him, exactly as
//      seed/stuti-images.ts already does for the Ganesha pages.
//
//  A group with no picture is a normal state, not a hole to be filled
//  with something approximate. Those groups get a drawn treatment
//  instead — see .bh-plate in styles/bhajans.css. Never illustrate a
//  devata with a picture of a different one.
// ─────────────────────────────────────────────────────────

export interface GroupImage {
  src: string;
  width: number;
  height: number;
  credit: string;
  /** Absent for a picture supplied without a recorded source. */
  sourceUrl?: string;
  /** Which part to keep when a frame crops it. */
  position?: string;
  alt: Record<Locale, string>;
}

