type CommonsEntry = { src: string; width: number; height: number; credit: string; sourceUrl: string };

const FROM_COMMONS = commons as Record<string, CommonsEntry>;

const IMAGES: Record<string, GroupImage> = {};

for (const [id, entry] of Object.entries(FROM_COMMONS)) {
  const alt = COMMONS_ALT[id];
  if (!alt) continue; // no alt text written yet means the picture is not used
  IMAGES[id] = { ...entry, position: "50% 40%", alt };
}
// The owner's photographs take precedence where he supplied one.
for (const [id, entry] of Object.entries(OWNED)) IMAGES[id] = entry;

/** The picture for a group, or undefined when it has none. */
export function groupImage(id: string): GroupImage | undefined {
  return IMAGES[id];
}

export function hasGroupImage(id: string): boolean {
  return id in IMAGES;
}

export function allGroupImages(): [string, GroupImage][] {
  return Object.entries(IMAGES);
}
